@import "tailwindcss";

@custom-variant dark (&:where(.dark, .dark *));

:root {
  --bg: #ffffff;
  --panel: #f7f7f8;
  --fg: #1c1d21;
  --muted: #6b6f7a;
  --line: #e3e4e8;
  --hover: #ececef;
  --active: #e1e7fb;
  --accent: #3b5bdb;
  --code-bg: #f1f2f5;
  font-family: ui-sans-serif, system-ui, -apple-system, "Segoe UI", Roboto, sans-serif;
}

:root.dark {
  --bg: #16171b;
  --panel: #1d1e23;
  --fg: #e6e7ea;
  --muted: #9a9ead;
  --line: #2e3038;
  --hover: #26282f;
  --active: #2b3352;
  --accent: #7c94f5;
  --code-bg: #23252c;
}

body {
  margin: 0;
  background: var(--bg);
  color: var(--fg);
}

@layer components {
  .btn {
    @apply inline-flex items-center justify-center rounded-md border border-(--line) bg-(--bg) px-3 py-1.5 text-sm font-medium transition-colors hover:bg-(--hover) cursor-pointer;
  }
  .btn-ghost {
    @apply border-transparent bg-transparent px-2;
  }
  .btn-primary {
    @apply border-transparent bg-(--accent) text-white hover:bg-(--accent) hover:opacity-90 dark:text-[#10121a];
  }
  .btn-danger {
    @apply border-transparent bg-red-600 text-white hover:bg-red-700;
  }
  .field {
    @apply rounded-md border border-(--line) bg-(--bg) px-3 py-1.5 text-sm outline-none focus:border-(--accent);
  }
}

:focus-visible {
  outline: 2px solid var(--accent);
  outline-offset: 1px;
}

/* Rendered Markdown */
.md-preview {
  line-height: 1.65;
  overflow-wrap: anywhere;
}
.md-preview > * + * { margin-top: 0.75em; }
.md-preview h1 { font-size: 1.75em; font-weight: 700; line-height: 1.25; }
.md-preview h2 { font-size: 1.4em; font-weight: 700; line-height: 1.3; margin-top: 1.2em; }
.md-preview h3 { font-size: 1.15em; font-weight: 600; margin-top: 1em; }
.md-preview h4, .md-preview h5, .md-preview h6 { font-weight: 600; }
.md-preview a { color: var(--accent); text-decoration: underline; }
.md-preview ul { list-style: disc; padding-left: 1.5em; }
.md-preview ol { list-style: decimal; padding-left: 1.5em; }
.md-preview li > ul, .md-preview li > ol { margin-top: 0.25em; }
.md-preview ul.task-list { list-style: none; padding-left: 0.25em; }
.md-preview li.task-item > ul, .md-preview li.task-item > ol { padding-left: 1.5em; }
.md-preview .task-item label { display: inline-flex; gap: 0.5em; align-items: baseline; cursor: pointer; }
.md-preview .task-item input { accent-color: var(--accent); width: 1em; height: 1em; transform: translateY(0.12em); cursor: pointer; }
.md-preview .task-item input:checked + span { color: var(--muted); text-decoration: line-through; }
.md-preview code { font-family: ui-monospace, SFMono-Regular, Menlo, Consolas, monospace; font-size: 0.9em; background: var(--code-bg); padding: 0.1em 0.35em; border-radius: 4px; }
.md-preview pre { background: var(--code-bg); padding: 0.85em 1em; border-radius: 8px; overflow-x: auto; }
.md-preview pre code { background: none; padding: 0; font-size: 0.85em; }
.md-preview blockquote { border-left: 3px solid var(--line); padding-left: 1em; color: var(--muted); }
.md-preview hr { border: 0; border-top: 1px solid var(--line); }

